parts.openscad_module:
$fn = 96;

// ── Parameters ───────────────────────────────────────────
leaf_length   = 40;    // total hinge length along X (pin axis)
leaf_width    = 20;    // leaf plate width along Y
leaf_thick    = 3;     // plate thickness (Z)
pin_d         = 5;     // pin nominal diameter
wall          = 1.5;   // barrel wall around pin
knuckle_count = 5;     // total knuckles (odd)
clearance     = 0.35;  // print-in-place gap

// ── Derived ──────────────────────────────────────────────
knuckle_l   = leaf_length / knuckle_count;    // 8 mm — NOT leaf_length/(2*count-1)
knuckle_OD  = pin_d + 2 * wall;              // 8 mm
bore_a      = pin_d + clearance;             // 5.35 mm — leaf A (tight, pin stays with A)
bore_b      = pin_d + 2 * clearance;         // 5.7 mm  — leaf B (clearance for rotation)
n_a         = (knuckle_count + 1) / 2;       // 3
n_b         = (knuckle_count - 1) / 2;       // 2
knuckle_z   = leaf_thick + knuckle_OD / 2;  // Z of shared pin axis

// ── Leaf A: plate +Y, 3 pin knuckles ─────────────────────
// Pin axis: along X, at y=0, z=knuckle_z
// All cylinders: rotate([0,90,0]) — NOT rotate([90,0,0])
module hinge_leaf_a() {
    // Plate — positive Y side, clearance gap from hinge joint
    translate([0, clearance, 0])
        cube([leaf_length, leaf_width, leaf_thick]);

    // n_a=3 pin knuckles at x = k/2, 5k/2, 9k/2
    for (i = [0 : n_a - 1]) {
        x_c = (2*i) * knuckle_l + knuckle_l / 2;
        translate([x_c, 0, knuckle_z])
            rotate([0, 90, 0])
                difference() {
                    cylinder(h = knuckle_l,     d = pin_d,  center = true);
                    cylinder(h = knuckle_l + 2, d = bore_a, center = true);
                }
    }
}

// ── Leaf B: plate -Y, 2 barrel knuckles ──────────────────
module hinge_leaf_b() {
    // Plate — negative Y side, clearance gap from hinge joint
    translate([0, -(leaf_width + clearance), 0])
        cube([leaf_length, leaf_width, leaf_thick]);

    // n_b=2 barrel knuckles at x = 3k/2, 7k/2
    for (i = [0 : n_b - 1]) {
        x_c = (2*i + 1) * knuckle_l + knuckle_l / 2;
        translate([x_c, 0, knuckle_z])
            rotate([0, 90, 0])
                difference() {
                    cylinder(h = knuckle_l - clearance, d = knuckle_OD, center = true);
                    cylinder(h = knuckle_l + 2,         d = bore_b,     center = true);
                }
    }
}

module five_knuckle_hinge() {
    hinge_leaf_a();
    hinge_leaf_b();
}

five_knuckle_hinge();
